import openpyxl

wb = openpyxl.load_workbook('init.xlsx')

for ws in wb.worksheets:
    # Delete rows from row 6 onward where column F is not "Accepted"
    # We iterate from bottom to top to avoid row shifting issues
    for r in range(ws.max_row, 5, -1):
        if ws.cell(r, 6).value != 'Accepted':
            ws.delete_rows(r, 1)

wb.save('output.xlsx')
print("done")
